// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1000, 500);

var VAL = '#aab1d6', COND = '#b5c97e', BW = 180, BH = 78, BASE_Y = 430;
var THERMAL = 3; // available promotion energy, in slider units

// Draw one band-gap panel. gapH in px (0 = bands touch, as in the conductor).
function drawPanel(x, gapH, opts) {
  opts = opts || {};
  var g = draw.group();
  var valTop = BASE_Y - BH, condBottom = valTop - gapH, condTop = condBottom - BH;
  g.rect(BW, BH).move(x, valTop).fill(VAL);
  g.rect(BW, BH).move(x, condTop).fill(COND);
  g.text('Valence').move(x + BW / 2, valTop + BH / 2 - 11).font({ size: 20, family: 'sans-serif', anchor: 'middle' });
  g.text('Conduction').move(x + BW / 2, condTop + BH / 2 - 11).font({ size: 20, family: 'sans-serif', anchor: 'middle' });
  // dashed gap edges (only when there is a visible gap)
  if (gapH > 2) {
    g.line(x, condBottom, x, valTop).stroke({ color: '#777', width: 1.5, dasharray: '7,6' });
    g.line(x + BW, condBottom, x + BW, valTop).stroke({ color: '#777', width: 1.5, dasharray: '7,6' });
  }
  if (opts.arrow && gapH > 40) {
    var ax = x + 45;
    var mk = draw.marker(10, 10, function (m) { m.path('M0,0 L10,5 L0,10 z').fill('#000'); }).ref(5, 5);
    var ln = g.line(ax, valTop - 4, ax, condBottom + 4).stroke({ color: '#000', width: 2 });
    ln.marker('start', mk); ln.marker('end', mk);
    g.text('Band gap').move(ax + 10, (valTop + condBottom) / 2 - 11).font({ size: 19, family: 'sans-serif' })
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  }
  return { group: g, x: x, gapH: gapH, valTop: valTop, condBottom: condBottom, condTop: condTop };
}

// Title sits just above the panel's own conduction band, not on a fixed baseline.
function panelTitle(p, t) {
  draw.text(t).move(p.x + BW / 2, p.condTop - 34)
    .font({ size: 22, weight: 'bold', family: 'sans-serif', anchor: 'middle' }).fill('#000');
}

// Reference panels — conductor bands touch (gap = 0), no orphaned label.
var pIns  = drawPanel(60, 175, { arrow: true });  panelTitle(pIns, 'Insulator');
var pSemi = drawPanel(320, 88, { arrow: true });  panelTitle(pSemi, 'Semiconductor');
var pCond = drawPanel(580, 0);                    panelTitle(pCond, 'Conductor');

// Divider separating the reference panels from the interactive panel.
draw.line(795, 60, 795, 470).stroke({ color: '#ddd', width: 1.5 });

// Interactive panel
var IX = 840, iGroup = null, igap = 5;
var iTitleTxt = draw.text('').font({ size: 18, weight: 'bold', family: 'sans-serif', anchor: 'middle' });
var iSubTxt = draw.text('Your material').font({ size: 12, family: 'sans-serif', anchor: 'middle' }).fill('#555');

function classFor(g) { return g < 2 ? 'Conductor' : (g < 6 ? 'Semiconductor' : 'Insulator'); }
function rebuildInteractive() {
  if (iGroup) iGroup.group.remove();
  iGroup = drawPanel(IX, igap * 17, { arrow: false });
  iTitleTxt.text(classFor(igap)).move(IX + BW / 2, iGroup.condTop - 32);
  iSubTxt.move(IX + BW / 2, iGroup.condTop - 14);
  iGroup.group.css('cursor', 'pointer');
  iGroup.group.on('click', function () { attemptPromotion(iGroup, igap); });
  iGroup.group.on('mousemove', function (e) { showTooltip('Gap = ' + igap.toFixed(1) + ' → ' + classFor(igap) + '. Click to promote an electron.', e); });
  iGroup.group.on('mouseleave', hideTooltip);
}
rebuildInteractive();

function update_bandGapSlider(v) { igap = v; rebuildInteractive(); }

// Wire clicks on reference panels too
[[pIns, 9, 'Insulator'], [pSemi, 4.5, 'Semiconductor'], [pCond, 0, 'Conductor']].forEach(function (e) {
  e[0].group.css('cursor', 'pointer');
  e[0].group.on('click', function () { attemptPromotion(e[0], e[1], e[2]); });
  e[0].group.on('mousemove', function (ev) { showTooltip(e[2] + ': gap ≈ ' + e[1] + ' units. Click to try promoting an electron.', ev); });
  e[0].group.on('mouseleave', hideTooltip);
});

// Electron promotion attempt: thermal energy THERMAL vs gap g
function attemptPromotion(p, g, name) {
  var cx = p.x + BW / 2, y0 = p.valTop - 12, yTop = p.condBottom + 14;
  var success = g <= THERMAL;
  var frac = g <= 0.01 ? 1 : Math.min(1, THERMAL / g);
  var yPeak = y0 - (y0 - yTop) * frac;
  var dot = draw.circle(16).center(cx, y0).fill('#d62728').stroke({ color: '#7a0000', width: 1.5 });
  var t0 = null, up = 700, down = 700;
  function phase1(ts) {
    if (!t0) t0 = ts;
    var k = Math.min(1, (ts - t0) / up);
    dot.center(cx, y0 + (yPeak - y0) * k);
    if (k < 1) requestAnimationFrame(phase1);
    else if (success) {
      dot.animate(300).opacity(0.35);
      showPopup((name || 'Your material') + ': promotion succeeded',
        'The electron crossed the band gap (gap ' + g.toFixed(1) + ' ≤ thermal energy ' + THERMAL + ') and now sits in the conduction band, where it can carry current. Small gap → easy conduction.');
      setTimeout(function () { dot.remove(); }, 2500);
    } else {
      var t1 = null;
      function phase2(ts2) {
        if (!t1) t1 = ts2;
        var k2 = Math.min(1, (ts2 - t1) / down);
        dot.center(cx, yPeak + (y0 - yPeak) * k2);
        if (k2 < 1) requestAnimationFrame(phase2);
        else {
          dot.animate(300).opacity(0);
          showPopup((name || 'Your material') + ': promotion failed',
            'The electron only climbed ' + Math.round(frac * 100) + '% of the gap before falling back — the band gap (' + g.toFixed(1) + ') exceeds the available energy (' + THERMAL + '). No free electrons, no current: this is an insulator.');
          setTimeout(function () { dot.remove(); }, 800);
        }
      }
      requestAnimationFrame(phase2);
    }
  }
  requestAnimationFrame(phase1);
}

// Demo step player
var steps = [
  { title: 'Compare the three panels', narration: 'All three diagrams are built identically — valence band below, conduction band above. Only the white band gap changes: largest for the insulator, half for the semiconductor, zero for the conductor, whose bands touch.', gap: 5 },
  { title: 'Try to promote an electron', narration: 'Click each panel to attempt a promotion. In the conductor the electron crosses effortlessly; in the insulator it falls far short — the gap is the energy barrier.', gap: 5 },
  { title: 'Sweep the gap', narration: 'Drag the slider: the material label on the right panel switches conductor → semiconductor → insulator. The categories are points on one continuous scale of band-gap energy.', gap: 2 }
];
var stepIdx = 0;
function showStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
  document.getElementById('bandGapSliderInput').value = s.gap;
  document.getElementById('bandGapSliderVal').value = s.gap;
  update_bandGapSlider(s.gap);
}
function nextStep() { showStep(stepIdx + 1); }
function prevStep() { showStep(stepIdx - 1); }
showStep(0);

window.__markRendered();
// @FIGURE_CODE_END

