<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px">Compare the three reference panels, then use the slider and click the right-hand panel.</p>
<div style="display:flex;gap:4px;align-items:center">
